/* ansi.c - wttr.in ANSI/UTF-8 text -> SymbOS C_TEXT_CTRL line buffers */
#include "ansi.h"
#include "glyphmap.h"   /* wt_glyph_cp[]  (generated by tools/mkfont.py) */
#include "colmap.h"     /* wt_colmap[256] (generated by tools/mkfont.py) */

#define NOCOL 0xFF      /* "terminal default" marker for fg/bg */
#define MAXP  8         /* max SGR parameters per escape sequence */

static unsigned char fg, bg;

/* Unicode code point -> font byte */
static unsigned char map_cp(unsigned short cp)
{
    unsigned char i;
    if (cp >= 0x20 && cp < 0x7F)
        return (unsigned char)cp;
    for (i = 0; i < WT_GLYPHS; ++i)
        if (wt_glyph_cp[i] == cp)
            return (unsigned char)(0x80 + i);
    return '?';
}

static unsigned char cur_attr(void)
{
    unsigned char f = (fg == NOCOL) ? WT_DEF_FG : fg;
    unsigned char b = (bg == NOCOL) ? WT_BG : bg;
    unsigned char a = WT_ATTR(f, b);
    if (a == 0)              /* 0x00 would end the string: pale yellow on */
        a = WT_ATTR(1, 0);   /* pale yellow is invisible anyway           */
    return a;
}

/* Apply one "ESC [ p1 ; p2 ; ... m" sequence */
static void apply_sgr(unsigned short *p, unsigned char n)
{
    unsigned char k;
    unsigned short v;
    unsigned char idx;

    for (k = 0; k < n; ++k) {
        v = p[k];
        if (v == 0) {
            fg = bg = NOCOL;
        } else if (v == 38 || v == 48) {
            if (k + 2 < n && p[k + 1] == 5) {            /* 256-colour */
                idx = wt_colmap[p[k + 2] & 0xFF];
                k += 2;
            } else if (k + 4 < n && p[k + 1] == 2) {     /* truecolour */
                idx = wt_colmap[16 + 36 * (p[k + 2] * 6 / 256)
                                   + 6 * (p[k + 3] * 6 / 256)
                                   + (p[k + 4] * 6 / 256)];
                k += 4;
            } else {
                continue;
            }
            if (v == 38) fg = idx; else bg = idx;
        } else if (v >= 30 && v <= 37) {
            fg = wt_colmap[v - 30];
        } else if (v >= 90 && v <= 97) {
            fg = wt_colmap[v - 90 + 8];
        } else if (v == 39) {
            fg = NOCOL;
        } else if (v >= 40 && v <= 47) {
            bg = wt_colmap[v - 40];
        } else if (v >= 100 && v <= 107) {
            bg = wt_colmap[v - 100 + 8];
        } else if (v == 49) {
            bg = NOCOL;
        }
        /* bold (1), underline, inverse etc. are ignored */
    }
}

unsigned char ansi_render(const unsigned char *s, unsigned short len,
                          char *lines, unsigned char maxlines)
{
    unsigned short i = 0;
    unsigned short p[MAXP];
    unsigned char np;
    unsigned char row = 0, col = 0, pos = 0;
    unsigned char c, ch, cur, emitted;
    unsigned short cp;
    char *out = lines;

    if (maxlines == 0)
        return 0;
    fg = bg = NOCOL;
    emitted = WT_DEFATTR;

    while (i < len) {
        c = s[i];

        /* ---- escape sequences ---- */
        if (c == 0x1B) {
            ++i;
            if (i < len && s[i] == '[') {
                ++i;
                np = 0;
                p[0] = 0;
                while (i < len) {
                    c = s[i++];
                    if (c >= '0' && c <= '9') {
                        p[np] = p[np] * 10 + (c - '0');
                    } else if (c == ';') {
                        if (np < MAXP - 1)
                            p[++np] = 0;
                    } else if (c >= 0x40 && c <= 0x7E) {
                        if (c == 'm')
                            apply_sgr(p, (unsigned char)(np + 1));
                        break;                  /* other CSI: ignored */
                    }
                }
            }
            continue;
        }

        /* ---- line ends ---- */
        if (c == '\n') {
            out[pos] = 0;
            if (++row >= maxlines)
                return row;
            out = lines + (unsigned short)row * WT_LINEBUF;
            pos = 0;
            col = 0;
            emitted = WT_DEFATTR;   /* each line control starts in default */
            ++i;
            continue;
        }
        if (c == '\r') {
            ++i;
            continue;
        }

        /* ---- UTF-8 decode ---- */
        if (c < 0x80) {
            cp = c;
            ++i;
        } else if ((c & 0xE0) == 0xC0 && i + 1 < len) {
            cp = ((unsigned short)(c & 0x1F) << 6) | (s[i + 1] & 0x3F);
            i += 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < len) {
            cp = ((unsigned short)(c & 0x0F) << 12)
               | ((unsigned short)(s[i + 1] & 0x3F) << 6)
               | (s[i + 2] & 0x3F);
            i += 3;
        } else if ((c & 0xF8) == 0xF0) {
            cp = '?';               /* 4-byte (emoji): beyond 16 bits */
            i += 4;
        } else {
            cp = '?';
            ++i;
        }

        if (cp == '\t')
            cp = ' ';
        if (cp < 0x20 || col >= WT_COLS)
            continue;

        /* ---- emit, adding a colour code only when it would show ---- */
        ch = map_cp(cp);
        cur = cur_attr();
        if (cur != emitted
            && !(ch == ' ' && (cur & 0x0F) == (emitted & 0x0F))
            && pos + 3 < WT_LINEBUF) {
            out[pos++] = 0x01;
            out[pos++] = (char)cur;
            emitted = cur;
        }
        if (pos + 1 < WT_LINEBUF) {
            out[pos++] = (char)ch;
            ++col;
        }
    }

    out[pos] = 0;
    return (unsigned char)(pos ? row + 1 : row);
}
